{
  "morphology_wrong_forms": [
    {
      "wrong_form": "effectivity",
      "explanation": "Often confused with effectiveness, but 'effectivity' is largely restricted to legal contexts (e.g., when a law takes effect) rather than general capability to produce results."
    },
    {
      "wrong_form": "effectlessness",
      "explanation": "A morphologically possible but non-standard coinage; standard English uses 'ineffectiveness'."
    },
    {
      "wrong_form": "effectivelyness",
      "explanation": "Double suffix error; adding '-ness' to the adverb 'effectively' creates an ungrammatical noun."
    }
  ],
  "l1_audio_confusables": [
    {
      "word": "affectiveness",
      "explanation": "Sounds very similar due to the unstressed initial vowel and shared root, but relates to psychology/emotions (affect) rather than producing a result."
    },
    {
      "word": "defectiveness",
      "explanation": "Phonetically overlaps in rapid speech ('-fectiveness'), but means having flaws or faults rather than being successful."
    },
    {
      "word": "attentiveness",
      "explanation": "Similar rhythmic structure and ending, but means paying close attention rather than achieving a desired outcome."
    }
  ],
  "collocation_distractors": [
    {
      "collocate": "fast",
      "explanation": "Native speakers use 'high' or 'proven' with effectiveness; 'fast' is used with speed or results, not the noun itself."
    },
    {
      "collocate": "strong",
      "explanation": "While 'strong' pairs with 'effect', it does not naturally collocate with 'effectiveness'; 'high' or 'maximum' are the correct modifiers."
    },
    {
      "collocate": "deep",
      "explanation": "'Deep' implies physical depth or emotional intensity, which does not collocate with the measurable success metric of effectiveness."
    }
  ],
  "collocation_wrong_collocate": {
    "collocate": "deep effectiveness",
    "explanation": "The adjective 'deep' cannot modify 'effectiveness'; use 'proven effectiveness' or 'overall effectiveness' instead."
  },
  "cloze_distractors": [
    {
      "option": "effect",
      "explanation": "A noun meaning a result, but syntactically and semantically incorrect in contexts requiring a measure of successful outcome."
    },
    {
      "option": "affect",
      "explanation": "Usually a verb, or a psychological noun, making it grammatically incompatible as a direct replacement for this noun."
    },
    {
      "option": "efficient",
      "explanation": "An adjective, whereas the sentence structure requires a noun."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "The new manager improved the company's effectiveness to finish the project by Friday.",
      "reason": "Effectiveness is a general measure of producing a result, not a specific deadline-driven action; 'efficiency' or 'ability' is more appropriate."
    },
    {
      "sentence": "We need to monitor the effectiveness of the rain.",
      "reason": "Natural weather phenomena do not have 'effectiveness' because they do not have a goal or intended outcome."
    },
    {
      "sentence": "Her effectiveness as a musician was shown by her beautiful guitar solo.",
      "reason": "Artistic beauty is evaluated by aesthetic criteria (e.g., skill, expressiveness), not functional effectiveness."
    }
  ],
  "spot_incorrect": {
    "sentence": "The marketing campaign proved its high effectiveness by increasing sales by fifty percent.",
    "planted_error": "high effectiveness",
    "error_description": "While 'high effectiveness' is occasionally used, standard business English strongly prefers 'proven effectiveness' or 'cost-effectiveness' in this specific metric context.",
    "corrected_version": "The marketing campaign proved its proven effectiveness by increasing sales by fifty percent."
  },
  "word_family_fake_forms": [
    "effectify",
    "effectation",
    "effectment"
  ],
  "particle_candidates": [
    "ga",
    "wo",
    "ni",
    "de"
  ]
}
